from bisect import bisect_right
from collections import Counter, defaultdict
from functools import lru_cache
from itertools import accumulate
import math

import numpy as np

ALPHA, CHAR_WEIGHT, CHAR_SMOOTH, CHAR_LIMIT = 4, .1, .2, 128
LETTERS = "abcdefghijklmnopqrstuvwxyz"
END = "$"


class Model:
    def __init__(self, train):
        self.train = train
        self.counts = Counter(train)
        self.next_counts = defaultdict(Counter)
        self.next_draws = defaultdict(list)
        chars = defaultdict(Counter)
        for previous, word in zip(train, train[1:]):
            self.next_counts[previous][word] += 1
            self.next_draws[previous].append(word)
        for word, count in self.counts.items():
            for a, b in zip(END + word, word + END):
                chars[a][b] += count
        self.rows = {}
        for previous in LETTERS + END:
            alphabet = LETTERS if previous == END else LETTERS + END
            weights = [chars[previous][c] + CHAR_SMOOTH for c in alphabet]
            cumulative = tuple(accumulate(weights))
            self.rows[previous] = alphabet, cumulative, {
                c: weight / cumulative[-1] for c, weight in zip(alphabet, weights)
            }

    @lru_cache(maxsize=100000)
    def base_probability(self, word):
        if not 0 < len(word) <= CHAR_LIMIT:
            raise ValueError(f"Unsupported normalization or word length: {word!r}")
        log_char = 0.0
        previous = END
        for char in word:
            if char not in LETTERS:
                raise ValueError(f"Unsupported character in normalized word: {word!r}")
            log_char += math.log(self.rows[previous][2][char])
            previous = char
        if len(word) < CHAR_LIMIT:
            log_char += math.log(self.rows[previous][2][END])
        return (1 - CHAR_WEIGHT) * self.counts[word] / len(self.train) + CHAR_WEIGHT * math.exp(log_char)

    def base_draw(self, rng):
        if rng.random() >= CHAR_WEIGHT:
            return rng.choice(self.train)
        word, previous = [], END
        for _ in range(CHAR_LIMIT):
            alphabet, cumulative, _ = self.rows[previous]
            char = alphabet[bisect_right(cumulative, rng.random() * cumulative[-1])]
            if char == END:
                break
            word.append(char)
            previous = char
        return "".join(word)

    def predictive_parts(self, words, windows):
        """Evaluate component probabilities on the same unmodified history."""
        base = np.array([self.base_probability(word) for word in words])
        bigram = base.copy()
        for i, (previous, word) in enumerate(zip(words, words[1:]), 1):
            row = self.next_counts.get(previous)
            if row:
                bigram[i] = (row.get(word, 0) + ALPHA * base[i]) / (len(self.next_draws[previous]) + ALPHA)
        by_window = {}
        for width in sorted(set(windows)):
            counter = Counter()
            prediction = np.empty(len(words))
            for i, word in enumerate(words):
                prediction[i] = (counter[word] + ALPHA * base[i]) / (min(i, width) + ALPHA)
                counter[word] += 1
                if i >= width:
                    counter[words[i - width]] -= 1
            by_window[width] = prediction
        return bigram, by_window

    def generate(self, n, settings, rng):
        output = []
        short, long, short_weight, long_weight = settings
        previous = None
        for i in range(n):
            choice = rng.random()
            if choice < short_weight + long_weight:
                width = short if choice < short_weight else long
                available = min(i, width)
                if available and rng.random() < available / (available + ALPHA):
                    word = output[i - 1 - rng.randrange(available)]
                else:
                    word = self.base_draw(rng)
            else:
                row = self.next_draws.get(previous)
                if row and rng.random() < len(row) / (len(row) + ALPHA):
                    word = rng.choice(row)
                else:
                    word = self.base_draw(rng)
            output.append(word)
            previous = word
        return output


def loss(parts, settings):
    base, by_window = parts
    short, long, short_weight, long_weight = settings
    probability = (1.0 - short_weight - long_weight) * base
    if short_weight:
        probability += short_weight * by_window[short]
    if long_weight:
        probability += long_weight * by_window[long]
    assert all(probability > 0)
    return float(-np.log2(probability).mean())
